import { useState, useRef, useCallback } from 'react';

const ScreenRecorder = ({
  canvasSelector = null,
  streamApiUrl = 'https://videostream.vegvisr.org',
  onRecordingComplete,
  className = '',
}) => {
  const [recording, setRecording] = useState(false);
  const [micEnabled, setMicEnabled] = useState(false);
  const [elapsed, setElapsed] = useState(0);
  const [showDialog, setShowDialog] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [uploadStatus, setUploadStatus] = useState('');

  const recorderRef = useRef(null);
  const chunksRef = useRef([]);
  const blobRef = useRef(null);
  const micStreamRef = useRef(null);
  const timerRef = useRef(null);
  const startTimeRef = useRef(0);
  const previewRef = useRef(null);

  const formatTime = (ms) => {
    const s = Math.floor(ms / 1000);
    const m = Math.floor(s / 60);
    return `${m}:${String(s % 60).padStart(2, '0')}`;
  };

  const getVideoStream = useCallback(() => {
    if (canvasSelector) {
      const canvas = document.querySelector(canvasSelector);
      if (canvas && canvas.captureStream) return canvas.captureStream(30);
    }
    return null;
  }, [canvasSelector]);

  const startRecording = useCallback(async () => {
    chunksRef.current = [];
    let videoStream = getVideoStream();

    if (!videoStream) {
      try {
        videoStream = await navigator.mediaDevices.getDisplayMedia({ video: { frameRate: 30 }, audio: false });
      } catch {
        return;
      }
    }

    const combined = new MediaStream();
    videoStream.getVideoTracks().forEach(t => combined.addTrack(t));

    if (micEnabled) {
      try {
        const audioStream = await navigator.mediaDevices.getUserMedia({ audio: true });
        micStreamRef.current = audioStream;
        audioStream.getAudioTracks().forEach(t => combined.addTrack(t));
      } catch {
        // proceed without mic
      }
    }

    const mimeType = ['video/webm;codecs=vp9', 'video/webm;codecs=vp8', 'video/webm']
      .find(m => MediaRecorder.isTypeSupported(m)) || 'video/webm';

    const recorder = new MediaRecorder(combined, { mimeType });
    recorder.ondataavailable = (e) => { if (e.data.size > 0) chunksRef.current.push(e.data); };
    recorder.onstop = () => {
      const blob = new Blob(chunksRef.current, { type: chunksRef.current[0]?.type || 'video/webm' });
      blobRef.current = blob;
      setShowDialog(true);
      setUploadStatus('');
      if (previewRef.current) {
        previewRef.current.src = URL.createObjectURL(blob);
        previewRef.current.muted = !micEnabled;
      }
      onRecordingComplete?.(blob);
    };

    recorder.start(100);
    recorderRef.current = recorder;
    startTimeRef.current = Date.now();
    setRecording(true);
    setElapsed(0);
    timerRef.current = setInterval(() => setElapsed(Date.now() - startTimeRef.current), 200);
  }, [micEnabled, getVideoStream, onRecordingComplete]);

  const stopRecording = useCallback(() => {
    if (recorderRef.current?.state !== 'inactive') {
      recorderRef.current.stop();
      recorderRef.current.stream.getTracks().forEach(t => t.stop());
    }
    micStreamRef.current?.getTracks().forEach(t => t.stop());
    micStreamRef.current = null;
    clearInterval(timerRef.current);
    setRecording(false);
  }, []);

  const handleDownload = () => {
    if (!blobRef.current) return;
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blobRef.current);
    a.download = `recording-${new Date().toISOString().slice(0, 19).replace(/:/g, '-')}.webm`;
    a.click();
    setShowDialog(false);
  };

  const handleUpload = async () => {
    if (!blobRef.current) return;
    setUploading(true);
    setUploadStatus('Requesting upload URL...');
    try {
      const res = await fetch(`${streamApiUrl}/direct-upload`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          maxDurationSeconds: 600,
          meta: { name: 'Screen Recording', source: 'vegvisr-ui-kit', recorded: new Date().toISOString() },
        }),
      });
      const data = await res.json();
      const uploadURL = data.uploadURL || data.result?.uploadURL;
      if (!uploadURL) throw new Error('No upload URL returned');

      setUploadStatus(`Uploading ${(blobRef.current.size / 1048576).toFixed(1)} MB...`);
      const form = new FormData();
      form.append('file', blobRef.current, 'recording.webm');
      const uploadRes = await fetch(uploadURL, { method: 'POST', body: form });
      let result = {};
      const ct = uploadRes.headers.get('content-type') || '';
      if (ct.includes('json')) {
        result = await uploadRes.json();
      } else {
        const text = await uploadRes.text();
        try { result = JSON.parse(text); } catch { result = {}; }
      }
      const uid = result.uid || result.result?.uid || '';
      setUploadStatus(uid ? `Uploaded! Video ID: ${uid}` : 'Uploaded successfully!');
      setTimeout(() => setShowDialog(false), 3000);
    } catch (err) {
      setUploadStatus(`Upload failed: ${err.message}`);
    } finally {
      setUploading(false);
    }
  };

  const handleDiscard = () => {
    if (previewRef.current?.src) URL.revokeObjectURL(previewRef.current.src);
    blobRef.current = null;
    chunksRef.current = [];
    setShowDialog(false);
  };

  return (
    <>
      {/* Mic + Record buttons */}
      <div className={`flex items-center gap-1 ${className}`}>
        <button
          type="button"
          onClick={() => setMicEnabled(!micEnabled)}
          title={micEnabled ? 'Mic ON — click to mute' : 'Mic OFF — click to enable'}
          className={`rounded-full border px-2 py-1 text-xs cursor-pointer transition-all ${
            micEnabled
              ? 'border-emerald-400/50 text-emerald-400'
              : 'border-white/20 text-white/40 hover:text-white/70'
          }`}
        >
          {micEnabled ? '\u{1F3A4}' : '\u{1F507}'}
        </button>
        <button
          type="button"
          onClick={recording ? stopRecording : startRecording}
          title={recording ? 'Stop recording' : 'Start recording'}
          className={`rounded-full border px-2 py-1 text-[10px] font-semibold uppercase tracking-wider cursor-pointer flex items-center gap-1.5 transition-all ${
            recording
              ? 'border-red-500/70 text-red-400 animate-pulse'
              : 'border-white/20 text-white/50 hover:text-white/80 hover:border-red-500/40'
          }`}
        >
          <span
            className={`w-2 h-2 rounded-full ${recording ? 'bg-red-500' : 'bg-white/30'}`}
          />
          <span>{recording ? 'Stop' : 'Rec'}</span>
          {recording && <span className="tabular-nums min-w-[2rem]">{formatTime(elapsed)}</span>}
        </button>
      </div>

      {/* Save dialog overlay */}
      {showDialog && (
        <div className="fixed inset-0 z-[200] bg-black/70 backdrop-blur-sm flex items-center justify-center">
          <div className="bg-slate-800 border border-white/15 rounded-2xl p-7 max-w-md w-[90%] shadow-2xl">
            <h3 className="text-base font-semibold text-white mb-1">Recording Complete</h3>
            <p className="text-xs text-slate-400 mb-4">
              {formatTime(elapsed)} &middot; {blobRef.current ? (blobRef.current.size / 1048576).toFixed(1) : '0'} MB
            </p>
            <video ref={previewRef} controls className="w-full rounded-lg mb-4 max-h-48 object-contain bg-slate-900" />
            <div className="flex gap-2">
              <button onClick={handleDiscard} className="flex-[0.5] py-2.5 rounded-lg border border-white/15 text-sm text-slate-400 hover:bg-white/5 cursor-pointer">
                Discard
              </button>
              <button onClick={handleDownload} className="flex-1 py-2.5 rounded-lg bg-slate-700 text-sm font-semibold text-white hover:bg-slate-600 cursor-pointer">
                &#x2B07; Download
              </button>
              <button onClick={handleUpload} disabled={uploading} className="flex-1 py-2.5 rounded-lg bg-sky-500 text-sm font-semibold text-white hover:bg-sky-400 disabled:opacity-50 cursor-pointer">
                &#x2601; Upload
              </button>
            </div>
            {uploadStatus && (
              <p className={`text-xs mt-3 ${uploadStatus.includes('failed') ? 'text-red-400' : 'text-sky-400'}`}>
                {uploadStatus}
              </p>
            )}
          </div>
        </div>
      )}
    </>
  );
};

export default ScreenRecorder;
